window.RTLBenchLSData.register("assets/d3c42dc33d6126928b58640ffe38f32a939250432471e192dee52b80d6e8a888.txt","# JasperGold SEC: sequential equivalence (golden vs revised RTL).\n# -sv = SystemVerilog mode (accepts Verilog + SV constructs; backward compatible).\n# Placeholders replaced by verification_tools.run_sec_remote:\n#   origen_138055.v0, origen_138055.v1, origen_138055, clk, rst_n\n#   clk -> \"clk\" or \"clk -both_edges\" for dual-edge designs\nset DESIGN_NAME_GOLDEN \"origen_138055.v0\"\nset DESIGN_NAME \"origen_138055.v1\"\nset TOP_NAME \"origen_138055\"\n\n\nclear -all\ncheck_sec -analyze -spec -sv ./input/rtl/${DESIGN_NAME_GOLDEN}.v\ncheck_sec -analyze -imp -sv ./input/rtl/${DESIGN_NAME}.v\ncheck_sec -elaborate -spec -top ${TOP_NAME} -disable_auto_bbox\ncheck_sec -elaborate -imp -top ${TOP_NAME} -disable_auto_bbox\n# check_sec -setup clock -infer reset -none\ncheck_sec -setup \ncheck_sec -map -auto\nclock clk \nreset rst_n\ncheck_sec -gen\n# check_sec -prove -strategy design_style -design_style_type clock_gating\n# check_sec -prove\ncheck_sec -prove -strategy proof\n");
